        optics.core[it] <= radius * radius
    };
    var cluster = -1
    for (i in optics.order) if (optics.reach[i] > radius * radius) {
        if (core[i]) labels[i] = ++cluster
    } else labels[i] = cluster
    return Clustering(labels, core)
